using BenchmarkDotNet.Attributes;
using BenchmarkDotNet.Configs;
using BenchmarkDotNet.Environments;
using BenchmarkDotNet.Jobs;
using BenchmarkDotNet.Running;
using BenchmarkDotNet.Toolchains.CsProj;
using TextAnalysis;

var config = DefaultConfig.Instance
    .AddJob(Job.ShortRun.WithRuntime(CoreRuntime.Core90).WithToolchain(CsProjCoreToolchain.NetCoreApp90))
    .AddJob(Job.ShortRun.WithRuntime(new CoreRuntime(RuntimeMoniker.Net100, "net10.0", ".NET 10.0")).WithToolchain(CsProjCoreToolchain.From(new Environments.NetCoreAppSettings("net10.0", null, "net10.0"))));

